// Agentic Design Workflow: Project Configuration
// This file is written once by the project lead via /initiate-design-project.
// Do not edit manually unless you are the project lead making a deliberate change.

window.PROJECT_CONFIG = {

  // Project identity
  project:     "Zimmermann (website redesign, handover)",
  client:      "Zimmermann",
  description: "Reimagined Zimmermann's digital retail experience, making it easier for customers to discover, explore and purchase collections online.",
  lead:        "Alrick Pagnon",
  initiated:   "2026-07-08",

  // Component prefix (set by /initiate-design-project, used by /extract and /handover)
  // Becomes the custom element tag namespace: "ds" → <ds-button>, "zimm" → <zimm-button>
  // Default: "ds". Must be lowercase, no spaces, no special characters.
  componentPrefix: "zimm",

  // Target stacks (set by /initiate-design-project, used by extraction skills)
  // Valid values: "ios", "android", "web", "react", "angular", "lwc"
  stacks: ["web", "react"],

  // Prototype build approach (set by /initiate-design-project, used by /start-prototype)
  // Valid values: "react-cdn" | "vanilla"
  // react-cdn: React 18 + ReactDOM + Babel via CDN, no build step, files open directly in browser
  // vanilla: plain HTML5, CSS, and JavaScript only
  prototypeStack: "react-cdn",

  // Accessibility standard ("AA" or "AAA")
  wcag: "AA",

  // Security level (set by /initiate-design-project, can be changed by the project lead)
  // "standard"   All capabilities. External URL fetching and web search enabled.
  // "elevated"   External URL fetching requires explicit per-URL confirmation. Web search flagged.
  // "restricted" No external URL fetching. No web search. Only local files, Figma, and local prototypes.
  securityLevel: "standard",

  // Web target browsers (used by /extract-specs for degradation prompts)
  targetBrowsers: [
    "last 2 Chrome versions",
    "last 2 Safari versions",
    "last 2 Firefox versions",
    "last 2 Edge versions"
  ],

  // Path overrides (optional, set by /setup for non-ADW projects)
  // Only add keys where your structure differs from ADW defaults.
  // Any key omitted here falls back to the ADW default defined in .claude/skills/_shared/portability.md.
  paths: {},

  // Access control: soft password gate for the viewer and component catalog.
  // Set a password here to require it on both. Leave commented out for no gate.
  // This is not real security (the password is visible in source). It prevents
  // accidental access from an unintended audience when a link is shared early.
  access: {
    // password: "",
  },

  // Catalog configuration (managed by /deploy-catalog, do not edit manually)
  catalog: {
    // deployUrl: "",    // Set by /deploy-catalog. The live Vercel URL for the component catalog.
  },

  // Viewer configuration (managed by /add-to-viewer and /deploy-viewer, do not edit manually)
  viewer: {
    theme:  "light",
    client: {
      name:       "Zimmermann",
      background: "#ffffff",
    },
    variants: [],
    // deployUrl: "",   // Set by /deploy-viewer. The live Vercel URL for the prototype viewer.
  },

};

